/*
Triggered when a meta-district is deleted from the Khan Academy for
Districts product. A meta-district is a node in the partnership hierarchy
used to group districts and other meta-districts into a tree.
*/
type MetaDistrictRemovedV1 struct {
	events.EventBase `eventType:"MetaDistrictRemoved" schemaVersion:"1"`

	/*
		  	The unique identifier for the meta-district being deleted in the Khan Academy
	for Districts product.
	*/
	MetaDistrictId string `json:"metaDistrictId"`
}

/*
Triggered when a meta-district is added or its state is updated in the Khan
Academy for Districts product. A meta-district is a node in the partnership hierarchy
used to group districts and other meta-districts into a tree.
Captures the current state of the meta-district including its position in the
hierarchy and the partnership it belongs to.
Removals are emitted via the MetaDistrictRemoved event instead.
*/
type MetaDistrictWrittenV1 struct {
	events.EventBase `eventType:"MetaDistrictWritten" schemaVersion:"1"`

	/*
		The unique identifier for this meta-district in the Khan Academy for Districts product.
	*/
	MetaDistrictId string `json:"metaDistrictId"`

	/*
		  	The display name of the meta-district in product.
	Empty string if not yet set.
	*/
	MetaDistrictName string `json:"metaDistrictName"`

	/*
		The timestamp when this meta-district was originally created in product.
	*/
	CreatedAt events.EventTime `json:"createdAt"`

	/*
		True for meta-district entities created for testing purposes.
	*/
	IsTest bool `json:"isTest"`

	/*
		  	The unique identifier of the parent node in the partnership hierarchy that this
	meta-district belongs to. Empty string if this is the root of the partnership hierarchy.
	*/
	ParentId string `json:"parentId"`

	/*
		  	The human-readable label for this meta-district's level in the partnership hierarchy.
	Labels are partnership-specific; for example a partnership may define levels such as
	"State", "District", and "Block" above the school level.
	*/
	LevelLabel string `json:"levelLabel"`

	/*
		  	The height of this meta-district in the partnership hierarchy tree, starting from the
	leaf nodes (schools are height 0). Districts are height 1, and meta-districts are
	height 2 or greater.
	*/
	LevelHeight int64 `json:"levelHeight"`

	/*
		  	The ISO-3166 alpha-2 country code for the country this meta-district belongs to
	(e.g. "US", "CA").
	*/
	CountryCode string `json:"countryCode"`

	/*
		  	The unique identifier of the partnership this meta-district belongs to. If this
	meta-district is the root of the partnership hierarchy, this will be the same as
	the meta-district's own ID (i.e., "metaDistrictId").
	*/
	PartnershipId string `json:"partnershipId"`
}

